package com.mobile.nodeide;

import android.content.SharedPreferences;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.appcompat.app.AlertDialog;import androidx.fragment.app.Fragment;import org.json.*;import java.io.*;import java.net.*;import java.util.concurrent.*;

/** OpenAI-compatible chat completions client. Tool calls always require explicit approval. */
public class AgentFragment extends Fragment {
 MainActivity a; TextView chat,provider; EditText prompt; Button send; SharedPreferences prefs; JSONArray messages=new JSONArray(); volatile boolean running;
 public View onCreateView(@NonNull LayoutInflater inf,ViewGroup parent,Bundle state){a=(MainActivity)requireActivity();prefs=a.getPreferences(0);LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setPadding(16,16,16,8);root.setBackgroundColor(0xff101117);
  TextView title=new TextView(a);title.setText("✦  AI Agent");title.setTextColor(0xfff2efff);title.setTextSize(24);root.addView(title);
  provider=new TextView(a);provider.setTextColor(0xffb9a8eb);provider.setPadding(0,12,0,12);root.addView(provider);updateProvider();provider.setOnClickListener(v->settings());
  chat=new TextView(a);chat.setTextColor(0xffe5e5ef);chat.setTextSize(15);chat.setText("Vamos construir.\n\nO agente pode ler e alterar arquivos e executar comandos após sua aprovação. Escolha um projeto e configure um provedor compatível com OpenAI.\n");ScrollView scroll=new ScrollView(a);scroll.addView(chat);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  prompt=new EditText(a);prompt.setTextColor(-1);prompt.setHintTextColor(0xff9a99a5);prompt.setHint("O que deve mudar a seguir?");prompt.setMinLines(2);root.addView(prompt);send=new Button(a);send.setText("Enviar  ➤");root.addView(send);send.setOnClickListener(v->start());return root;
 }
 void updateProvider(){provider.setText("⚙  "+prefs.getString("provider","Custom Provider")+" · "+prefs.getString("model","Configurar modelo")+"  ▾");}
 void settings(){String[] providers={"Custom Provider","Gemini (OpenAI compatible)","SambaNova","Ollama Cloud","Cohere (compatibility API)","Claude (Anthropic API não suportada)"};new AlertDialog.Builder(a).setTitle("Provedores").setItems(providers,(d,n)->configure(providers[n],n)).show();}
 void configure(String name,int n){String[] urls={"https://", "https://generativelanguage.googleapis.com/v1beta/openai", "https://api.sambanova.ai/v1", "https://ollama.com/v1", "https://api.cohere.ai/compatibility/v1", "https://"};LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding  (20,0,20,0);EditText url=new EditText(a),key=new EditText(a),model=new EditText(a);url.setHint("Base URL HTTPS (terminando em /v1)");url.setText(n==0?prefs.getString("url",urls[n]):urls[n]);key.setHint("API key (armazenada no app)");key.setSingleLine();key.setInputType(129);key.setText(prefs.getString("key",""));model.setHint("Modelo");model.setText(prefs.getString("model",""));box.addView(url);box.addView(key);box.addView(model);new AlertDialog.Builder(a).setTitle(name).setMessage("API OpenAI-compatible /chat/completions. Claude via API Anthropic não está implementado. A chave é armazenada nas preferências privadas, sem criptografia.").setView(box).setPositiveButton("Salvar",(d,w)->{prefs.edit().putString("provider",name).putString("url",url.getText().toString().trim()).putString("key",key.getText().toString().trim()).putString("model",model.getText().toString().trim()).apply();updateProvider();}).setNegativeButton("Cancelar",null).show();}
 void log(String s){a.runOnUiThread(()->{if(isAdded())chat.append("\n"+s+"\n");});}
 void start(){String text=prompt.getText().toString().trim();if(text.isEmpty()||running)return;if(a.project==null){a.message("Abra um projeto primeiro");return;}String url=prefs.getString("url","");if(!url.startsWith("https://")||prefs.getString("model","").isEmpty()){a.message("Configure URL HTTPS e modelo");return;}prompt.setText("");chat.append("\nVocê: "+text+"\n");try{messages.put(new JSONObject().put("role","user").put("content",text));}catch(JSONException ignored){}running=true;send.setEnabled(false);File root=a.project;new Thread(()->{try{loop(root);}catch(Exception e){log("Erro: "+e.getMessage());}finally{running=false;a.runOnUiThread(()->{if(isAdded())send.setEnabled(true);});}}).start();}
 void loop(File root)throws Exception{
  for(int step=0;step<8;step++){
   JSONObject request=new JSONObject().put("model",prefs.getString("model","")).put("messages",messages).put("tools",tools());
   String base=prefs.getString("url","").replaceAll("/+$","");HttpURLConnection conn=(HttpURLConnection)new URL(base+"/chat/completions").openConnection();conn.setRequestMethod("POST");conn.setConnectTimeout(20000);conn.setReadTimeout(90000);conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");String key=prefs.getString("key","");if(!key.isEmpty())conn.setRequestProperty("Authorization","Bearer "+key);try(OutputStream out=conn.getOutputStream()){out.write(request.toString().getBytes("UTF-8"));}int status=conn.getResponseCode();InputStream stream=status>=400?conn.getErrorStream():conn.getInputStream();String response;try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);response=out.toString("UTF-8");}finally{conn.disconnect();}if(status>=400)throw new IOException("HTTP "+status+": "+response);
   JSONObject msg=new JSONObject(response).getJSONArray("choices").getJSONObject(0).getJSONObject("message");messages.put(msg);String content=msg.optString("content","");if(!content.isEmpty()&&!content.equals("null"))log("Agente: "+content);JSONArray calls=msg.optJSONArray("tool_calls");if(calls==null||calls.length()==0)return;
   for(int j=0;j<calls.length();j++){JSONObject call=calls.getJSONObject(j),fn=call.getJSONObject("function");String name=fn.getString("name"),args=fn.optString("arguments","{}");log("Solicitando ação: "+name+" "+args);String result;if(!approve(name,args))result="Ação recusada pelo usuário.";else try{result=tool(root,name,new JSONObject(args));}catch(Exception e){result="Erro: "+e.getMessage();}log("Resultado: "+result);messages.put(new JSONObject().put("role","tool").put("tool_call_id",call.getString("id")).put("content",result));}
  }log("Limite de ações atingido. Envie outra mensagem para continuar.");
 }
 boolean approve(String name,String args)throws InterruptedException{CountDownLatch latch=new CountDownLatch(1);boolean[] yes={false};a.runOnUiThread(()->{if(!isAdded()){latch.countDown();return;}new AlertDialog.Builder(a).setTitle("Permitir ação do agente?").setMessage(name+"\n"+args+"\n\nComandos usam as permissões do app e podem alterar dados.").setPositiveButton("Permitir",(d,w)->{yes[0]=true;latch.countDown();}).setNegativeButton("Recusar",(d,w)->latch.countDown()).setOnCancelListener(d->latch.countDown()).show();});return latch.await(5,TimeUnit.MINUTES)&&yes[0];}
 File safe(File root,String path)throws IOException{File f=new File(root,path);String base=root.getCanonicalPath();String p=f.getCanonicalPath();if(!p.equals(base)&&!p.startsWith(base+File.separator))throw new IOException("Caminho fora do projeto");return f;}
 String tool(File root,String name,JSONObject arg)throws Exception{File f=safe(root,arg.optString("path","."));switch(name){case "list_files":String[] files=f.list();return files==null?"Não é um diretório":String.join("\n",files);case "read_file":if(f.length()>200000)throw new IOException("Arquivo muito grande");return MainActivity.read(f);case "write_file":MainActivity.write(f,arg.getString("content"));return "Arquivo gravado: "+arg.getString("path");case "delete_file":if(f.equals(root)||!f.isFile()||!f.delete())throw new IOException("Não foi possível excluir arquivo");return "Arquivo excluído";case "run_command":String cmd=arg.getString("command");File capture=File.createTempFile("agent", ".log",a.getCacheDir());try{Process p=new ProcessBuilder("/system/bin/sh","-c",cmd).directory(root).redirectErrorStream(true).redirectOutput(capture).start();if(!p.waitFor(30,TimeUnit.SECONDS)){p.destroyForcibly();return "Comando excedeu 30 segundos e foi interrompido.";}String out=MainActivity.read(capture);return "exit "+p.exitValue()+"\n"+out.substring(0,Math.min(out.length(),12000));}finally{capture.delete();}default:throw new IOException("Ferramenta desconhecida");}}
 JSONArray tools()throws JSONException{JSONArray arr=new JSONArray();arr.put(spec("list_files","Lista arquivos de um diretório",false,false));arr.put(spec("read_file","Lê arquivo de texto",false,false));arr.put(spec("write_file","Cria ou substitui arquivo de texto",true,false));arr.put(spec("delete_file","Exclui um arquivo",false,false));arr.put(spec("run_command","Executa comando shell no projeto",false,true));return arr;}
 JSONObject spec(String name,String description,boolean content,boolean command)throws JSONException{JSONObject props=new JSONObject();JSONArray required=new JSONArray();if(command){props.put("command",new JSONObject().put("type","string"));required.put("command");}else{props.put("path",new JSONObject().put("type","string").put("description","Caminho relativo ao projeto"));required.put("path");if(content){props.put("content",new JSONObject().put("type","string"));required.put("content");}}return new JSONObject().put("type","function").put("function",new JSONObject().put("name",name).put("description",description).put("parameters",new JSONObject().put("type","object").put("properties",props).put("required",required)));}
}
